package com.aliothmoon.maafw.once;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.aliothmoon.maafw.once.NativeUiStructureParser.*;
public class NativeUiStructureParserTest {
    private static Node n(int i,String text,String desc){return new Node(i,i==0?-1:0,true,true,text,desc);}
    private static Result parseText(String text){return NativeUiStructureParser.parse(List.of(n(0,text,null)));}
    @Test public void englishExplicitTargetIsKnown(){var r=parseText("Read to earn, , 7 out of 31 points earned");assertEquals(Status.KNOWN,r.reading().status());assertEquals(7,r.reading().current());assertEquals(31,r.reading().target());assertEquals(Unit.EXPLICIT_TEXT_POINTS,r.reading().unit());assertEquals(Status.UNKNOWN,r.search().status());assertFalse(r.actionAuthority());assertEquals(CounterSource.UI_STRUCTURE,r.counterSource());}
    @Test public void chineseExactSpacesAreKnown(){var r=parseText("搜索以赚取, , 已赚取 3 积分(需要 61 积分)");assertEquals(Status.KNOWN,r.search().status());assertEquals(61,r.search().target());}
    @Test public void sameNodeIdenticalFieldsDeduplicate(){String s="Read to earn, , 0 out of 30 points earned";var r=NativeUiStructureParser.parse(List.of(n(0,s,s)));assertEquals(1,r.reading().matchCount());assertEquals(Status.KNOWN,r.reading().status());}
    @Test public void separateNodesRemainAmbiguousEvenSameCounter(){String s="Read to earn, , 0 out of 30 points earned";var r=NativeUiStructureParser.parse(List.of(n(0,s,null),n(1,s,null)));assertEquals(Status.AMBIGUOUS,r.reading().status());assertEquals(2,r.reading().matchCount());assertEquals(0,r.reading().target());}
    @Test public void distinctFieldsSameNodeRemainAmbiguous(){var r=NativeUiStructureParser.parse(List.of(n(0,"Read to earn, , 0 out of 30 points earned","阅读以赚取, , 已赚取 0 积分(需要 30 积分)")));assertEquals(Status.AMBIGUOUS,r.reading().status());}
    @Test public void shorthandNeverInventsTargets(){for(String text:List.of("Read to earn, 30 points earned","Search to earn, 60 points earned","Read to earn","30/30")){var r=parseText(text);assertEquals(Status.UNKNOWN,r.reading().status());assertEquals(Status.UNKNOWN,r.search().status());}}
    @Test public void invalidNumericValuesFailTask(){for(String x:List.of("-1","+1","1.0","abc","2147483648","10001")){assertEquals(x,Status.INVALID,parseText("Read to earn, , "+x+" out of 10000 points earned").reading().status());}for(String d:List.of("0","-2","10001","999999999999999999")){assertEquals(Status.INVALID,parseText("Search to earn, , 0 out of "+d+" points earned").search().status());}}
    @Test public void overTargetInvalidAndLimitsAccepted(){assertEquals(Status.INVALID,parseText("Read to earn, , 31 out of 30 points earned").reading().status());var r=parseText("Search to earn, , 10000 out of 10000 points earned");assertEquals(Status.KNOWN,r.search().status());assertEquals(10000,r.search().current());}
    @Test public void wrongFullSummarySchemaInvalid(){for(String s:List.of("Read to earn, , 2 out of 3 points earned suffix","Read to earn, , 2/3","阅读以赚取, , 已赚取2积分(需要3积分)")){assertEquals(s,Status.INVALID,parseText(s).reading().status());}}
    @Test public void noSubstringOrCaseNormalization(){for(String s:List.of("prefix Read to earn, , 2 out of 3 points earned","read to earn, , 2 out of 3 points earned"," Read to earn, , 2 out of 3 points earned")){assertEquals(Status.UNKNOWN,parseText(s).reading().status());}}
    @Test public void differentTasksCannotBorrowOrPoison(){var r=NativeUiStructureParser.parse(List.of(n(0,"Read to earn, , -1 out of 30 points earned",null),n(1,"Search to earn, , 2 out of 60 points earned",null)));assertEquals(Status.INVALID,r.reading().status());assertEquals(Status.KNOWN,r.search().status());}
    @Test public void noParentOrNearestNodeMerge(){var r=NativeUiStructureParser.parse(List.of(n(0,"Read to earn",null),n(1,"7 out of 30 points earned",null)));assertEquals(Status.UNKNOWN,r.reading().status());}
    @Test public void invisibleAndForeignFieldsCannotQualify(){String s="Read to earn, , 3 out of 30 points earned";var r=NativeUiStructureParser.parse(List.of(new Node(0,-1,false,true,s,null),new Node(1,0,true,false,s,null)));assertEquals(Status.UNKNOWN,r.reading().status());}
    @Test public void structuralInvalidityRejectsBothTasks(){for(List<Node> nodes:List.of(List.of(n(0,null,null),n(0,null,null)),List.of(new Node(0,9,true,true,null,null)),List.of(n(0,null,null),new Node(1,-1,true,true,null,null)))){var r=NativeUiStructureParser.parse(nodes);assertEquals(Status.INVALID,r.reading().status());assertEquals(Status.INVALID,r.search().status());}}
    @Test public void boundedNodesAndFields(){assertEquals(Status.INVALID,NativeUiStructureParser.parse(null).reading().status());assertEquals(Status.INVALID,parseText("x".repeat(2049)).reading().status());List<Node> rows=new ArrayList<>();for(int i=0;i<513;i++)rows.add(n(i,null,null));assertEquals(Status.INVALID,NativeUiStructureParser.parse(rows).reading().status());rows.clear();for(int i=0;i<17;i++)rows.add(n(i,"x".repeat(2048),null));assertEquals(Status.INVALID,NativeUiStructureParser.parse(rows).reading().status());}
    @Test public void noRawTextInResult(){String text="private unknown content";var r=parseText(text);assertFalse(r.toString().contains(text));assertEquals(Status.UNKNOWN,r.reading().status());}
    @Test public void invalidPrecedesDuplicateAmbiguity(){String s="Read to earn, , 0 out of 30 points earned";var r=NativeUiStructureParser.parse(List.of(n(0,s,null),n(1,s,null),n(2,"Read to earn, , -1 out of 30 points earned",null)));assertEquals(Status.INVALID,r.reading().status());assertEquals(3,r.reading().matchCount());}
}
